<?php
function renderEventoWorkspace(array $event, int $yo): void
{
    $date = (new DateTimeImmutable($event['inicio_utc'], new DateTimeZone('UTC')))->setTimezone(new DateTimeZone($event['zona']));
    $past = strtotime($event['fin_utc'] . ' UTC') <= time();
    $cancelled = $event['estado'] === 'cancelado';
    $months = ['01' => 'ENE','02' => 'FEB','03' => 'MAR','04' => 'ABR','05' => 'MAY','06' => 'JUN','07' => 'JUL','08' => 'AGO','09' => 'SEP','10' => 'OCT','11' => 'NOV','12' => 'DIC'];
    ?><article class="card scene-event-card <?= $cancelled ? 'is-cancelled' : '' ?>" id="evento-<?= (int)$event['id'] ?>"><header><div class="scene-event-date"><strong><?= $date->format('d') ?></strong><span><?= $months[$date->format('m')] ?></span></div><div><span class="community-kicker"><?= $cancelled ? 'Cancelado' : ($past ? 'Evento pasado' : e($event['ciudad'])) ?></span><h2><a href="evento.php?id=<?= (int)$event['id'] ?>"><?= e($event['titulo']) ?></a></h2><p><?= $date->format('H:i') ?> · <?= e($event['zona']) ?> · <?= $date->format('d/m/Y') ?></p></div></header><p class="scene-event-place"><?= e($event['sede'] ?: 'Sede por confirmar') ?></p><?php if ($event['descripcion']): ?><p class="scene-event-description"><?= nl2br(e($event['descripcion'])) ?></p><?php endif; ?><p class="scene-event-organizer">Organiza <a href="musico.php?id=<?= (int)$event['creador_id'] ?>"><?= e($event['nombre'] . ' ' . $event['apellido']) ?></a></p><div class="scene-event-counts"><span><?= (int)($event['asistentes'] ?? 0) ?> van</span><span><?= (int)($event['interesados'] ?? 0) ?> interesados</span></div><div class="scene-event-tools"><a class="btn btn-ghost" href="evento-ics.php?id=<?= (int)$event['id'] ?>" data-native-navigation>Mi calendario ↓</a><details data-sheet data-sheet-title="Cartel del evento"><summary class="btn btn-ghost">Ver cartel</summary><figure class="scene-event-poster"><img src="cartel-evento.php?id=<?= (int)$event['id'] ?>" loading="lazy" width="900" height="1200" alt="Cartel de <?= e($event['titulo']) ?>"><figcaption><a href="cartel-evento.php?id=<?= (int)$event['id'] ?>" download="musicmad-evento-<?= (int)$event['id'] ?>.svg" class="btn btn-primary">Descargar cartel</a></figcaption></figure></details></div>
 <?php if (!$cancelled && !$past): ?><form method="POST" action="<?= e(rutaAplicacion('evento-accion.php', 'POST')) ?>" class="scene-event-rsvp"><?= csrfCampo() ?><input type="hidden" name="accion" value="rsvp"><input type="hidden" name="id" value="<?= (int)$event['id'] ?>"><label>Tu respuesta<select name="estado"><option value="asistire" <?= ($event['mi_estado'] ?? '') === 'asistire' ? 'selected' : '' ?>>Voy a asistir</option><option value="interesado" <?= ($event['mi_estado'] ?? '') === 'interesado' ? 'selected' : '' ?>>Me interesa</option></select></label><label class="scene-event-reminder"><input type="checkbox" name="aviso" value="1" <?= !empty($event['aviso']) ? 'checked' : '' ?>> Recordarme en MusicMad</label><button class="btn btn-primary" type="submit">Guardar respuesta</button></form><?php if (!empty($event['mi_estado'])): ?><form method="POST" action="<?= e(rutaAplicacion('evento-accion.php', 'POST')) ?>" class="scene-event-remove"><?= csrfCampo() ?><input type="hidden" name="accion" value="quitar"><input type="hidden" name="id" value="<?= (int)$event['id'] ?>"><button type="submit" class="btn btn-ghost">Cancelar mi respuesta</button></form><?php endif; ?><?php endif; ?>
 <?php if ((int)$event['creador_id'] === $yo && !$cancelled && !$past): ?><details class="scene-event-edit" data-sheet data-sheet-title="Editar evento"><summary>Editar y administrar</summary><?php formularioEventoWorkspace($event); ?><a class="btn btn-ghost" href="ubicacion.php?tipo=evento&amp;id=<?= (int)$event['id'] ?>">Zona aproximada en el mapa</a><form method="POST" action="<?= e(rutaAplicacion('evento-accion.php', 'POST')) ?>" data-confirm="¿Cancelar este evento y avisar a quienes respondieron?" class="scene-event-cancel"><?= csrfCampo() ?><input type="hidden" name="accion" value="cancelar"><input type="hidden" name="id" value="<?= (int)$event['id'] ?>"><button type="submit" class="btn btn-danger">Cancelar evento</button></form></details><?php endif; ?></article><?php
}
